fn array_split(a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
    let n = a.len();

    // Any split point k in [0, n] preserves order via (a[..k], a[k..]).
    // To satisfy "if n > 1, both parts are strictly shorter than n",
    // we choose k = n/2, which makes both lengths <= n-1 when n > 1.
    let k = n / 2;

    // `split_off(k)` leaves `left` as the first k elements,
    // and returns the tail (from k to end) as `right`.
    let mut left = a;
    let right = left.split_off(k);

    (left, right)
}

